(x, y, t) => {
  const s = (ax, ay, fx, fy, px, py) => {
    const sx = ax + Math.sin(t * fx + px) * ay;
    const sy = ax * 0.6 + Math.cos(t * fy + py) * ay * 0.6;
    return [sx, sy];
  };
  const srcs = [s(160, 110, 0.6, 0.4, 0, 0), s(320, 100, 0.5, 0.7, 2.1, 1.3), s(240, 130, 0.3, 0.5, 4.2, 2.6), s(100, 80, 0.7, 0.35, 1.0, 3.8), s(380, 90, 0.45, 0.55, 3.3, 5.1)];
  const ds = srcs.map(([sx, sy]) => Math.sqrt((x - sx) ** 2 + (y - sy) ** 2));
  const freqs = [0.08, 0.1, 0.065, 0.09, 0.075];
  const speeds = [2.0, 1.7, 2.3, 1.5, 2.6];
  const waves = ds.map((d, i) => Math.sin(d * freqs[i] - t * speeds[i]));
  const activator = (waves[0] + waves[1] + waves[2] + waves[3] + waves[4]) / 5;
  const w4 = Math.sin(x * 0.045 + y * 0.028 + t * 0.8);
  const w5 = Math.sin(x * 0.032 - y * 0.048 + t * 1.1);
  const w6 = Math.sin((x + y) * 0.13 + t * 2.8) * 0.18;
  const w7 = Math.sin((x - y) * 0.11 - t * 2.2) * 0.18;
  const w8 = Math.sin(x * 0.02 * Math.sin(t * 0.3) + y * 0.02 * Math.cos(t * 0.25) + t * 0.6);
  const inhibitor = (w4 + w5 + w8) / 3;
  const reaction = activator - inhibitor * 0.75 + w6 + w7;
  const spot = Math.tanh(reaction * 2.2);
  const cx = 240, cy = 120;
  const dx = x - cx, dy = y - cy;
  const dist = Math.sqrt(dx * dx + dy * dy);
  const ang = Math.atan2(dy, dx);
  const radial = Math.sin(dist * 0.035 - t * 1.4);
  const angular = Math.sin(ang * 8 + t * 0.35 + dist * 0.01);
  const spiral = Math.sin(ang * 3 + dist * 0.025 - t * 0.8);
  const pattern2 = Math.tanh((radial + angular * 0.4 + spiral * 0.3) * 1.8);
  const warp = Math.sin(x * 0.01 + t * 0.4) * Math.cos(y * 0.012 - t * 0.3) * 8;
  const wx = x + warp, wy = y + Math.cos(x * 0.012 - t * 0.35) * Math.sin(y * 0.01 + t * 0.45) * 8;
  const lattice = Math.sin(wx * 0.15) * Math.sin(wy * 0.15);
  const lattice2 = Math.sin((wx + wy) * 0.105) * Math.cos((wx - wy) * 0.105);
  const micro = Math.tanh((lattice + lattice2) * 1.5) * 0.25;
  const energy = Math.abs(activator - inhibitor) + Math.abs(w6) + Math.abs(w7);
  const eNorm = Math.tanh(energy * 1.2);
  const blend = spot * 0.45 + pattern2 * 0.3 + micro * 0.15 + eNorm * 0.1;
  const v = blend * 0.5 + 0.5;
  const pal = [[8, 12, 58], [15, 72, 115], [22, 148, 135], [180, 200, 80], [230, 170, 50], [210, 85, 55], [140, 30, 65], [8, 12, 58]];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.82 + Math.sin(reaction * Math.PI * 1.2) * 0.12 + eNorm * 0.06;
  const sat = 0.9 + Math.sin(pattern2 * Math.PI) * 0.1;
  return [
    Math.min(255, Math.max(0, (pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f) * lum * sat)) | 0,
    Math.min(255, Math.max(0, (pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f) * lum)) | 0,
    Math.min(255, Math.max(0, (pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f) * lum * (2 - sat))) | 0
  ];
}
